import sys, json, math
sys.path.insert(0, "/workspace/scripts")
from calibrate2 import build_once, set_note, render, measure_freq, expected_rate

# Candidate "sum" anchors known broadly reasonable (from L=300 clean sweep),
# ordered to try a spread of registers first.
CANDIDATES = [25, 33, 37, 40, 44, 47, 51, 56, 60, 65, 72, 77, 80, 85, 91, 96,
              102, 106, 111, 117, 30, 42, 49, 53, 61, 68, 71, 82, 87, 90, 95, 99, 104, 114, 116]

def note_relative_for_sum(s):
    if s <= 96:
        return s, 0
    else:
        return 96, s - 96

def rate_const(sum_, finetune=0):
    return expected_rate(sum_, finetune)

def try_combo(sum_, L, finetune, target):
    note, rel = note_relative_for_sum(sum_)
    if rel < -48 or rel > 71 or note < 1 or note > 96 or L < 8:
        return None
    set_note(note, L, rel, finetune)
    render()
    exp_freq = rate_const(sum_, finetune) / L
    fmax = min(19500, exp_freq*2.5+80)
    fmin = max(4, exp_freq*0.4)
    f = measure_freq('/tmp/cal.wav', fmin=fmin, fmax=fmax)
    if f <= 0:
        return None
    err = abs(f - target) / target
    return f, err, note, rel, L, finetune

def calibrate_note(target, tol=0.004, verbose=False):
    best = None
    for s in CANDIDATES:
        rc = rate_const(s, 0)
        L = round(rc / target)
        if L < 32:
            continue
        for ft in [0, 8, -8, 16, -16, 24, -24, 4, -4, 32, -32]:
            res = try_combo(s, L, ft, target)
            if res is None:
                continue
            f, err, note, rel, Lr, ftr = res
            if verbose:
                print(f"  try sum={s} L={L} ft={ft} -> f={f:.3f} err={err*100:.3f}%")
            if best is None or err < best[1]:
                best = (f, err, note, rel, Lr, ftr, s)
            if err < tol:
                return {"target": target, "measured": f, "err_pct": err*100,
                        "note": note, "relative_note": rel, "loop_length": Lr,
                        "finetune": ftr, "sum": s}
        # also try L+-1 adjustments with ft=0 for fine correction
        for dL in (-1, 1, -2, 2):
            res = try_combo(s, L+dL, 0, target)
            if res is None:
                continue
            f, err, note, rel, Lr, ftr = res
            if best is None or err < best[1]:
                best = (f, err, note, rel, Lr, ftr, s)
            if err < tol:
                return {"target": target, "measured": f, "err_pct": err*100,
                        "note": note, "relative_note": rel, "loop_length": Lr,
                        "finetune": ftr, "sum": s}
    if best is None:
        return None
    f, err, note, rel, Lr, ftr, s = best
    return {"target": target, "measured": f, "err_pct": err*100,
            "note": note, "relative_note": rel, "loop_length": Lr,
            "finetune": ftr, "sum": s, "best_effort": True}

if __name__ == "__main__":
    build_once()
    targets = json.loads(sys.argv[1]) if len(sys.argv) > 1 else [110, 220, 440]
    results = {}
    for name, f in targets.items():
        r = calibrate_note(f)
        results[name] = r
        print(name, f, "->", r)
    json.dump(results, open("/tmp/tuning_results.json", "w"), indent=2)
EOF
echo written"}

